    /// <summary>
    /// A stored glossary that still equals the previous default was never edited: it moves to the
    /// current default. Anything else is the organisation's own text and is left alone.
    /// </summary>
    public static string? UpgradeGlossary(string? stored) =>
        SameText(stored, PreviousGlossary) ? Glossary : stored;

    private static bool SameText(string? a, string b) =>
        string.Equals(
            string.Join('\n', (a ?? "").Split('\n', StringSplitOptions.TrimEntries)).Trim(),
            string.Join('\n', b.Split('\n', StringSplitOptions.TrimEntries)).Trim(),
            StringComparison.Ordinal);

    /// <summary>A stored IVS text that still equals the previous default was never edited: it moves to the current one.</summary>
    public static string? UpgradeIvsStandards(string? stored) =>
        SameText(stored, PreviousIvsStandards) ? IvsStandards : stored;

    /// <summary>A stored §31 that still equals the short previous list was never edited: it moves to the full one.</summary>
    public static string? UpgradeTerms(string? stored) =>
        SameText(stored, PreviousTerms) ? Terms : stored;

    /// <summary>A stored §32 that still equals the previous list was never edited: it moves to the v3 one.</summary>
    public static string? UpgradeRestrictions(string? stored) =>
        SameText(stored, PreviousRestrictions) ? Restrictions : stored;

    public static string Clip(string? value, string fallback, int max = 20000)
    {
        var t = (value ?? "").Trim();
        if (t.Length == 0) return fallback;
        return t.Length <= max ? t : t[..max];
    }

    public static IReadOnlyList<string> NormalizeLibrary(IEnumerable<string>? items)
    {
        var library = (items ?? [])
            .Select(x => (x ?? "").Trim())
            .Where(x => x.Length is > 0 and <= 2000)
            .Distinct(StringComparer.Ordinal)
            .Take(100)
            .ToList();
        return library.Count == 0 ? SpecialAssumptionLibrary.ToList() : library;
    }

    public static string ForSectionKey(string key) => key switch
    {
        ValuationReportSectionKeys.KeyInputs => KeyInputsText,
        ValuationReportSectionKeys.ProfessionalStandards => ProfessionalStandards,
        ValuationReportSectionKeys.Independence => Independence,
        ValuationReportSectionKeys.ResearchScope => ResearchScopeText,
        ValuationReportSectionKeys.Restrictions => Restrictions,
        ValuationReportSectionKeys.Terms => Terms,
        ValuationReportSectionKeys.IvsStandards => IvsStandards,
        ValuationReportSectionKeys.Glossary => Glossary,
        _ => ValuationReportFrozenTextLayers.ForSectionKey(key),
    };
}
